INSERT INTO wp_postmeta (post_id, meta_key, meta_value) VALUES (12257, '_iss_editorial_landing', '{\"schema_version\":1,\"skin\":\"frontpage\",\"variant\":\"standard\",\"features\":[],\"sections\":[{\"type\":\"statement\",\"kicker\":\"\",\"title\":\"Schöneweide ist eines der größten industriell geprägten Denkmal-Ensembles in Deutschland.\",\"body\":\"Der Industriesalon führt Gäste aus aller Welt durch die herausragenden Zeugnisse historischer Industriearchitektur, die in Schöneweide in seltener Vielfalt erhalten sind. Die angebotenen Touren geben vielfältige Einblicke in die Entwicklung zu einem Berliner Zukunftsort - eine spannende Mischung aus nachhaltigem Städtebau, Wissenschaft, Kunst und Produktion.\",\"links\":[{\"label\":\"Schöneweide entdecken\",\"url\":\"/schoneweide/\"}],\"treatment\":\"statement.lead\"},{\"type\":\"gateway\",\"kicker\":\"Vor Ort\",\"title\":\"Den Industriesalon entdecken\",\"body\":\"Der Industriesalon lässt sich vor Ort als Rundgang, Ausstellung und öffentlicher Termin erleben. Die kulturellen Zugänge stehen hier vor der Serviceebene.\",\"anchor\":\"vor-ort\",\"items\":[{\"label\":\"Führungen\",\"text\":\"Entdecken Sie Industriegeschichte, Stadtraum und Transformation in unseren öffentlichen und buchbaren Rundgängen.\",\"url\":\"/fuehrungen/\",\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"26050\",\"label\":\"\",\"thumbnail\":\"\"}]},{\"label\":\"Ausstellungen\",\"text\":\"Objekte, Bilder und Dokumente zeigen Industriegeschichte im Zusammenhang von Ort und Produktion.\",\"url\":\"/ausstellungen/\",\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"26047\",\"label\":\"\",\"thumbnail\":\"\"}]},{\"label\":\"Veranstaltungen\",\"text\":\"Vorträge, Gespräche und kleinere Formate bringen Gegenwart und Industriekultur zusammen.\",\"url\":\"/veranstaltungen/\",\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"26048\",\"label\":\"\",\"thumbnail\":\"\"}]}],\"treatment\":\"gateway.cards\"},{\"type\":\"dynamic_slot\",\"kicker\":\"\",\"title\":\"\",\"body\":\"\",\"anchor\":\"projekte\",\"slot_key\":\"front-projects\",\"treatment\":\"slot.projects\"},{\"type\":\"dynamic_slot\",\"kicker\":\"\",\"title\":\"Demnächst\",\"body\":\"\",\"anchor\":\"gegenwart\",\"slot_key\":\"front-timeline\",\"treatment\":\"slot.timeline\"},{\"type\":\"feature\",\"kicker\":\"Raum nutzen\",\"title\":\"Salon mieten\",\"body\":\"Veranstaltungen, Workshops und Empfänge in einer ehemaligen Produktionshalle, mitten im historischen Industriegebiet von Schöneweide.\\n\\nStühle, Tische, WLAN, Tonanlage, Beamer und Leinwand können nach Bedarf genutzt werden.\",\"anchor\":\"raum-nutzen\",\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"13313\",\"label\":\"Salonvermietung im Industriesalon\",\"thumbnail\":\"\"}],\"links\":[{\"label\":\"Details und Anfrage\",\"url\":\"/salon-vermietung/\"}],\"facts\":[{\"value\":\"650 m²\",\"label\":\"Halle mit Ausstellung und Galerie\"},{\"value\":\"350 m²\",\"label\":\"Ausstellungsraum, 7 m Höhe\"},{\"value\":\"100 m²\",\"label\":\"Veranstaltungsraum mit Bühne und Terrasse\"}],\"treatment\":\"feature.media-panel\"},{\"type\":\"gateway\",\"kicker\":\"Archiv & Wissen\",\"title\":\"Quellen, Erinnerung und Entwicklung\",\"body\":\"Archiv, Sammlungen, Publikationen und Videos machen die historischen Schichten Schöneweides sichtbar. Sie dokumentieren industrielle Entwicklungen, gesellschaftliche Veränderungen und die Menschen, die den Standort geprägt haben.\",\"anchor\":\"archiv-wissen\",\"items\":[{\"label\":\"Sammlungen\",\"text\":\"\",\"url\":\"/sammlungen/\",\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"13327\",\"label\":\"\",\"thumbnail\":\"\"}]},{\"label\":\"Publikationen\",\"text\":\"\",\"url\":\"/publikationen/\",\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"12426\",\"label\":\"\",\"thumbnail\":\"\"}]},{\"label\":\"Archiv\",\"text\":\"\",\"url\":\"/archiv/\",\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"5348\",\"label\":\"\",\"thumbnail\":\"\"}]},{\"label\":\"Videos\",\"text\":\"\",\"url\":\"/videos/\",\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"26041\",\"label\":\"\",\"thumbnail\":\"\"}]}],\"treatment\":\"gateway.cards\"},{\"type\":\"feature\",\"kicker\":\"Industriesalon\",\"title\":\"Über uns\",\"body\":\"Der Industriesalon Schöneweide ist Museum, Lernort und Ausgangspunkt, um den Stadtteil über seine Industriegeschichte, seine Architektur und seine heutigen Veränderungen zu verstehen.\",\"anchor\":\"industriesalon\",\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"180\",\"label\":\"Industriesalon Schöneweide\",\"thumbnail\":\"\"}],\"links\":[{\"label\":\"Weiter\",\"url\":\"/about/\"}],\"facts\":[{\"value\":\"Arbeitsweise\",\"label\":\"Mitglieder werden über Aktivitäten und Entwicklungen auf dem Laufenden gehalten. Gleichzeitig bleibt Raum für Begegnung, Feiern, Gespräche und die gemeinsame Arbeit an einem besonderen Ort.\"},{\"value\":\"Mitarbeit\",\"label\":\"Der Industriesalon lebt nicht nur von Beständen, sondern von Menschen, die führen, ordnen, recherchieren, aufbauen, zuhören oder einfach mit anpacken.\"},{\"value\":\"Mitglied werden\",\"label\":\"Wer den Industriesalon unterstützen möchte, kann Mitglied werden, mitarbeiten oder spenden. Die Formen sind verschieden, aber sie sichern denselben Ort.\"},{\"value\":\"Netzwerk im Stadtteil\",\"label\":\"Der Industriesalon arbeitet mit Nachbarschaft, Initiativen, Schulen, Kulturpartnern und lokalen Akteuren zusammen. Dadurch entsteht ein Ort, der nicht nur bewahrt, sondern Austausch ermöglicht und Schöneweide als gemeinsamen Erinnerungs- und Erfahrungsraum stärkt.\"}],\"treatment\":\"feature.microblocks\"},{\"type\":\"dynamic_slot\",\"kicker\":\"\",\"title\":\"\",\"body\":\"\",\"anchor\":\"besuch\",\"slot_key\":\"front-visit-info\",\"treatment\":\"slot.visit-info\"},{\"type\":\"dynamic_slot\",\"kicker\":\"\",\"title\":\"\",\"body\":\"\",\"slot_key\":\"front-newsletter\",\"treatment\":\"slot.newsletter\"}]}');

